/** Inline SVG for a skill icon key, or null when there is no brand icon for it. */
function skill_icon_svg(string $key): ?string {
    $icon = SKILL_ICONS[strtolower($key)] ?? null;
    if ($icon === null) {
        return null;
    }
    $rule = isset($icon['rule']) ? ' fill-rule="' . $icon['rule'] . '"' : '';
    $viewBox = $icon['view'] ?? '0 0 24 24';
    $inner = isset($icon['raw']) ? $icon['raw'] : '<path fill="currentColor"' . $rule . ' d="' . $icon['path'] . '"/>';
    // scale enlarges one brand icon that draws smaller than the others, without touching the grid
    $style = isset($icon['scale']) ? ' style="transform:scale(' . $icon['scale'] . ')"' : '';
    return '<svg class="skill-svg" viewBox="' . $viewBox . '" role="img" aria-label="' . htmlspecialchars($icon['title']) . '"' . $style . '>' . $inner . '</svg>';
}
